def _parse_version(version_str):
    # Strip build metadata
    if '+' in version_str:
        version_str, _ = version_str.split('+', 1)

    # Separate pre-release
    if '-' in version_str:
        core, pre = version_str.split('-', 1)
    else:
        core, pre = version_str, None

    # Parse core (MAJOR.MINOR.PATCH)
    major, minor, patch = map(int, core.split('.'))

    # Parse pre-release identifiers
    pre_identifiers = []
    if pre is not None:
        for part in pre.split('.'):
            if part.isdigit():
                pre_identifiers.append(int(part))
            else:
                pre_identifiers.append(part)

    return (major, minor, patch), pre_identifiers

def _compare_pre_identifiers(a_ids, b_ids):
    # Compare common identifiers
    for a_id, b_id in zip(a_ids, b_ids):
        a_is_int = isinstance(a_id, int)
        b_is_int = isinstance(b_id, int)

        # Numeric identifiers always have lower precedence than non-numeric identifiers
        if a_is_int and not b_is_int:
            return -1
        if not a_is_int and b_is_int:
            return 1

        # Compare of same type
        if a_id < b_id:
            return -1
        if a_id > b_id:
            return 1

    # If all compared identifiers are equal, the one with more identifiers has higher precedence
    if len(a_ids) < len(b_ids):
        return -1
    if len(a_ids) > len(b_ids):
        return 1

    return 0

def compare_versions(a, b):
    a_core, a_pre = _parse_version(a)
    b_core, b_pre = _parse_version(b)

    # Compare major, minor, patch
    if a_core < b_core:
        return -1
    if a_core > b_core:
        return 1

    # Core versions are equal, check pre-release
    # A larger set of pre-release fields has a higher precedence than a smaller set,
    # if all of the preceding identifiers are equal.
    # Also: A normal version has higher precedence than a pre-release one.
    if a_pre is None and b_pre is not None:
        return 1
    if a_pre is not None and b_pre is None:
        return -1
    if a_pre is None and b_pre is None:
        return 0

    return _compare_pre_identifiers(a_pre, b_pre)
